<template><AppShell :title="pageTitle"><template #default="{ can, setError }"><v-tabs v-model="tab" grow density="compact"><v-tab value="schedule">스케줄</v-tab><v-tab value="leave">휴가</v-tab><v-tab value="dayoff">희망휴무</v-tab></v-tabs><v-window v-model="tab" class="mt-4"><v-window-item value="schedule"><v-list><v-list-item v-for="s in data.schedules" :key="s.id" :title="`${s.work_date} · ${s.user?.name}`" :subtitle="`${s.work_code?.name ?? s.status} ${s.scheduled_start_time ?? ''}~${s.scheduled_end_time ?? ''}`"/></v-list><v-empty-state v-if="!data.schedules.length" title="스케줄이 없습니다."/></v-window-item><v-window-item value="leave"><v-form @submit.prevent="applyLeave(setError)"><v-select v-model="leave.leave_type" :items="leaveTypes" label="휴가 종류" variant="outlined"/><div class="d-flex ga-2"><v-text-field v-model="leave.start_date" type="date" label="시작일" variant="outlined"/><v-text-field v-model="leave.end_date" type="date" label="종료일" variant="outlined"/></div><v-number-input v-model="leave.amount" label="차감 일수" :step="0.5" :min="0.5" variant="outlined"/><v-textarea v-model="leave.reason" label="신청 사유" variant="outlined" rows="2"/><v-btn type="submit" block>휴가 신청</v-btn></v-form><v-divider class="my-4"/><v-list><v-list-item v-for="r in data.leave_requests" :key="r.id" :title="`${r.user?.name} · ${r.start_date}~${r.end_date}`" :subtitle="`${r.leave_type} · ${r.status}`"><template #append><div v-if="can('leave.manage')&&r.status==='pending'" class="d-flex ga-1"><v-btn size="x-small" @click="review('leave',r.id,'approved',setError)">승인</v-btn><v-btn size="x-small" variant="outlined" @click="review('leave',r.id,'rejected',setError)">반려</v-btn></div></template></v-list-item></v-list></v-window-item><v-window-item value="dayoff"><v-text-field v-model="dayoffDate" type="date" label="희망휴무일" variant="outlined"/><v-textarea v-model="dayoffReason" label="사유" variant="outlined" rows="2"/><v-btn block @click="applyDayOff(setError)">희망휴무 신청</v-btn><v-divider class="my-4"/><v-list><v-list-item v-for="r in data.day_off_requests" :key="r.id" :title="`${r.user?.name} · ${r.target_year}.${r.target_month}`" :subtitle="`${r.dates?.map(d=>d.request_date).join(', ')} · ${r.status}`"><template #append><div v-if="can('leave.manage')&&r.status==='pending'" class="d-flex ga-1"><v-btn size="x-small" @click="review('dayoff',r.id,'approved',setError)">승인</v-btn><v-btn size="x-small" variant="outlined" @click="review('dayoff',r.id,'rejected',setError)">반려</v-btn></div></template></v-list-item></v-list></v-window-item></v-window></template></AppShell></template>
<script setup>
import{onMounted,ref}from'vue';import AppShell from'../../components/layout/AppShell.vue';const pageTitle='근무 관리';const tab=ref('schedule');const data=ref({schedules:[],attendances:[],leave_requests:[],day_off_requests:[],work_codes:[]});const today=new Date().toISOString().slice(0,10);const leave=ref({leave_type:'annual',day_unit:'full_day',start_date:today,end_date:today,amount:1,reason:''});const leaveTypes=[{title:'연차',value:'annual'},{title:'반차',value:'half_day'}];const dayoffDate=ref(today),dayoffReason=ref('');async function load(){data.value=(await window.axios.get('/tillwhite/api/work')).data;}async function applyLeave(err){try{await window.axios.post('/tillwhite/api/work/leave',leave.value);await load();}catch(e){err(e.response?.data?.message??'신청 실패');}}async function applyDayOff(err){try{await window.axios.post('/tillwhite/api/work/day-off',{dates:[dayoffDate.value],reason:dayoffReason.value});await load();}catch(e){err(e.response?.data?.message??'신청 실패');}}async function review(type,id,status,err){try{await window.axios.put(`/tillwhite/api/work/requests/${type}/${id}`,{status});await load();}catch(e){err(e.response?.data?.message??'처리 실패');}}onMounted(load);
</script>
